+/** Selects a supported request language by quality, falling back to the configured language. */
+export function requestLanguage(headers, fallback = "en") {
+  const header = Object.entries(headers).find(([name]) => name.toLowerCase() === "accept-language")?.[1];
+  if (typeof header !== "string") return fallback;
+  const preferences = header.split(",").map((entry, index) => {
+    const [tag, ...parameters] = entry.trim().split(";");
+    let quality = 1;
+    for (const parameter of parameters) {
+      const match = /^q\s*=\s*(.*)$/i.exec(parameter.trim());
+      if (!match || !/^(?:0(?:\.\d{0,3})?|1(?:\.0{0,3})?)$/.test(match[1])) {
+        quality = 0;
+        break;
+      }
+      quality = Number(match[1]);
+    }
+    const language = /^[a-z]{2}(?:-[a-z0-9]{1,8})*$/i.test(tag) ? tag.toLowerCase().split("-")[0] : null;
+    return { language, quality, index };
+  });
+  preferences.sort((a, b) => b.quality - a.quality || a.index - b.index);
+  return preferences.find(({ language, quality }) => quality > 0 && LANGUAGES.includes(language))?.language ?? fallback;
+}
